from typing import Dict, List
from hourglass.models import Shift
from hourglass.errors import ProjectError
from collections import defaultdict


# ---
def timesheet_lines(shifts: List[Shift]) -> List[str]:
    if not shifts:
        raise ProjectError("no shifts")
    if any(not item.worker.strip() for item in shifts):
        raise ProjectError("blank worker name")
    rows = _tally(shifts)
    order = sorted(rows.items(), key=_rank)
    return [_line(name, *vals) for name, vals in order]


def _rank(pair) -> tuple:
    return (-pair[1][1], pair[0])


def _tally(shifts: List[Shift]) -> Dict[str, List[int]]:
    rows = defaultdict(lambda: [0, 0])
    for item in shifts:
        rows[item.worker][0] += 1
        rows[item.worker][1] += item.span.minutes
    return rows


def _line(name: str, count: int, minutes: int) -> str:
    hours = minutes / 60
    return f"{name}: {count} shifts, {hours:.1f} hours"

